#!/usr/bin/env node
// Generated files (committed, so the CLI stays a single dependency-free file and the
// Worker needs no build step of its own):
//   cli/bin/mailmint.mjs                          ← cli/src/*.mjs + @agent-socket/sdk, one file
//   worker/src/vendor/agent-socket-sdk.client.js  ← @agent-socket/sdk (browser ESM, served at /assets/)
//   worker/src/vendor/socket-tools.client.js      ← cli/src/socket-tools.mjs (served at /assets/)
//
//   node scripts/build.mjs           # regenerate
//   node scripts/build.mjs --check   # fail if any generated file is stale (run by `npm test`)
import { build } from "esbuild";
import { chmodSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");
const HEADER = "// GENERATED by scripts/build.mjs — edit the sources, then run `node scripts/build.mjs`.\n";

async function bundle(entry, platform) {
  const out = await build({
    entryPoints: [join(root, entry)],
    bundle: true,
    format: "esm",
    platform,
    target: platform === "node" ? "node22" : "es2022",
    write: false,
    legalComments: "inline",
    logLevel: "silent",
  });
  return out.outputFiles[0].text;
}

const outputs = {
  "cli/bin/mailmint.mjs": "#!/usr/bin/env node\n" + HEADER + (await bundle("cli/src/cli.mjs", "node")).replace(/^#!.*\n/m, ""),
  "worker/src/vendor/agent-socket-sdk.client.js": HEADER + (await bundle("node_modules/@agent-socket/sdk/dist/index.js", "browser")),
  "worker/src/vendor/socket-tools.client.js": HEADER + readFileSync(join(root, "cli/src/socket-tools.mjs"), "utf8"),
};

let stale = 0;
for (const [file, content] of Object.entries(outputs)) {
  const path = join(root, file);
  let current = null;
  try {
    current = readFileSync(path, "utf8");
  } catch {}
  if (current === content) continue;
  if (check) {
    console.error(`stale: ${file} (run: node scripts/build.mjs)`);
    stale++;
    continue;
  }
  writeFileSync(path, content);
  if (file.endsWith("mailmint.mjs")) chmodSync(path, 0o755);
  console.log(`wrote ${file}`);
}
if (stale) process.exit(1);
